"use strict";
const V="89", KEY="fafatraining_coach_v89";
const LEVELS=["Débutant","Intermédiaire","Avancé"];
const UNIVERSES=["Musculation","Renforcement / Poids du corps","Cross Training","Functional Training","HYROX","Cardio","Running / Trail","Boxe / Combat","Préparation physique","Endurance","Force","Puissance","Explosivité","Plyométrie","Agilité / Coordination","Mobilité / Souplesse","Prévention / Reprise","Calisthenics","Circuit Training","Collectif","Récupération"];
